      stroke-linejoin: round;
    }

    /* Mirror back arrow in RTL */
    :dir(rtl) .icon-directional {
      transform: scaleX(-1);
    }

    .header-title {
      font-size: 1.2rem;
      font-weight: 600;
    }

    /* Cart items */
    .cart-items {
