    }

    .stepper button {
      width: 32px;
      height: 32px;
      border: 1px solid var(--border);
      background-color: #fff;
      border-radius: 50%;
      cursor: pointer;
      font-size: 1.2rem;
      line-height: 1;
      display: flex;
      align-items: center;
      justify-content: center;
