      <button class="back-btn" aria-label="رجوع">
        <svg class="icon-directional" viewBox="0 0 24 24">
          <path d="M15 19l-7-7 7-7" />
        </svg>
      </button>
      <h1 class="header-title">إتمام الطلب</h1>
