    <main class="cart-items">
      <!-- Item 1 -->
      <div class="cart-item" data-item="1">
        <div class="item-photo"></div>
        <div class="item-details">
          <div>
            <div class="item-name">تفاحة خضراء</div>
            <div class="item-price"><span class="ltr">5.50 AED</span></div>
          </div>
          <div class="stepper">
            <button class="decrease" aria-label="خفض">−</button>
            <input type="text" class="quantity" value="2" readonly>
            <button class="increase" aria-label="زيادة">+</button>
          </div>
        </div>
        <div class="item-total"><span class="ltr">11.00 AED</span></div>
      </div>

