            <input type="text" class="quantity" value="1" readonly>
            <button class="increase" aria-label="زيادة">+</button>
          </div>
        </div>
        <div class="item-total"><span class="ltr">3.75 AED</span></div>
      </div>

      <!-- Item 3 -->
      <div class="cart-item" data-item="3">
        <div class="item-photo"></div>
        <div class="item-details">
