            <div class="item-price"><span class="ltr">12.00 AED</span></div>
          </div>
          <div class="stepper">
            <button class="decrease" aria-label="خفض">−</button>
            <input type="text" class="quantity" value="3" readonly>
            <button class="increase" aria-label="زيادة">+</button>
          </div>
