        <button class="promo-btn">تطبيق</button>
      </div>
    </section>

    <section class="summary-section">
      <div class="summary-row">
        <span>المجموع الفرعي</span>
        <span class="summary-subtotal"><span class="ltr">50.75 AED</span></span>
      </div>
      <div class="summary-row">
        <span>التوصيل</span>
        <span class="summary-delivery"><span class="ltr">5.00 AED</span></span>
      </div>
      <div class="summary-row">
        <span>ضريبة القيمة المضافة 5%</span>
        <span class="summary-vat"><span class="ltr">2.79 AED</span></span>
      </div>
      <div class="summary-row total">
        <span>الإجمالي</span>
        <span class="summary-total"><span class="ltr">58.54 AED</span></span>
      </div>
    </section>
