  <button class="place-order-btn">إتمام الطلب</button>

  <script>
    // Unit prices per item
    const itemPrices = {
      1: 5.50,
      2: 3.75,
      3: 12.00
    };
    const deliveryFee = 5.00;
    const vatRate = 0.05;

    // Helper: format a number as AED with isolated Latin run
    function formatAED(amount) {
      const formatted = new Intl.NumberFormat('en-AE', {
        minimumFractionDigits: 2,
        maximumFractionDigits: 2
      }).format(amount);
      return `<span class="ltr">${formatted} AED</span>`;
    }

    // Update item line totals and order summary
    function updateTotals() {
      let subtotal = 0;

      document.querySelectorAll('.cart-item').forEach(item => {
        const id = item.getAttribute('data-item');
        const qty = parseInt(item.querySelector('.quantity').value, 10);
        const price = itemPrices[id];
        const lineTotal = price * qty;

        item.querySelector('.item-total').innerHTML = formatAED(lineTotal);
        subtotal += lineTotal;
      });

      const vat = subtotal * vatRate;
      const total = subtotal + deliveryFee + vat;

      document.querySelector('.summary-subtotal').innerHTML = formatAED(subtotal);
      document.querySelector('.summary-delivery').innerHTML = formatAED(deliveryFee);
      document.querySelector('.summary-vat').innerHTML = formatAED(vat);
      document.querySelector('.summary-total').innerHTML = formatAED(total);
    }

    // Stepper event handlers
    document.querySelectorAll('.stepper').forEach(stepper => {
      const decreaseBtn = stepper.querySelector('.decrease');
      const increaseBtn = stepper.querySelector('.increase');
      const input = stepper.querySelector('.quantity');

      decreaseBtn.addEventListener('click', () => {
        let val = parseInt(input.value, 10);
        if (val > 1) {
          input.value = val - 1;
          updateTotals();
        }
      });

      increaseBtn.addEventListener('click', () => {
        let val = parseInt(input.value, 10);
        input.value = val + 1;
        updateTotals();
      });
    });

    // Promo code apply
    document.querySelector('.promo-btn').addEventListener('click', () => {
      const code = document.querySelector('.promo-input').value.trim();
      if (code) {
        alert(`تم تطبيق الرمز: ${code}`);
        // In a real app, this would trigger a discount recalculation
      }
    });

    // Place order button
    document.querySelector('.place-order-btn').addEventListener('click', () => {
      alert('تم إرسال الطلب بنجاح!');
    });

    // Initial calculation
    updateTotals();
  </script>
